#include "palette_import.h"
#include <fstream>
#include <iostream>
#include <chrono>
using namespace moon;
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
std::vector<std::uint8_t> bytes(const std::string& s){return {s.begin(),s.end()};}
int main(){try{
 // Original byte fixtures and expectations: platform_palette.rs tests 1227/1236/1259.
 auto gpl=decodeImportedPalette(bytes("GIMP Palette\nName: Ordered\n#\n17 34 51 First\n68 85 102 Second\n"),"ordered.GPL");require(gpl.name=="ordered"&&gpl.colors==std::vector<Pixel>({0xff332211,0xff665544})&&gpl.columns==2,"legacy GPL file order/name");
 std::string rows;for(int i=0;i<115;++i)rows+=std::to_string(i)+" "+std::to_string(i)+" "+std::to_string(i)+" Color"+std::to_string(i)+"\n";auto padded=decodeImportedPalette(bytes(rows),"yozu.txt");require(padded.columns==16&&padded.colors.size()==115&&padded.slots.size()==128&&padded.slots[114]==114&&!padded.slots[115]&&!padded.slots.back(),"legacy partial final row padding");
 auto text=decodeImportedPalette(bytes("\xef\xbb\xbf#112233\n//skip\n;skip\n112233 named\nrgb(1,2,3,999)\n-2 10 20 30 .5\n+4,5,6,7\n"),"edge.hex");require(text.colors==std::vector<Pixel>({0xff332211,0xff030201,0xff1e140a,0x07060504}),"text comments/u16 filtering/alpha/file order");
 auto generic=decodeImportedPalette(bytes("[\"#11223380\",[1,0.5,0,0.5],{\"R\":10,\"G\":20,\"B\":30,\"A\":300},\"bad\",[999,0,0],{\"r\":1,\"g\":0,\"b\":0}]"),"generic.json");require(generic.colors==std::vector<Pixel>({0x80332211,0x800080ff,0xff1e140a,0xff0000ff}),"JSON normalized RGB/independent alpha/skip invalid");
 auto object=decodeImportedPalette(bytes("{\"colors\":false,\"palette\":[\"#112233\"],\"swatches\":[\"#445566\"]}"),"object.json");require(object.colors==std::vector<Pixel>({0xff332211}),"JSON first array priority");
 std::vector<std::uint8_t> act(772);act[0]=17;act[1]=34;act[2]=51;act[3]=68;act[4]=85;act[5]=102;act[769]=2;act[771]=1;auto imported=decodeImportedPalette(act,"two.act");require(imported.colors==std::vector<Pixel>({0xff332211,0x00665544}),"legacy ACT transparency without reorder");require(decodeImportedPalette(act,"two.pal").colors==imported.colors,"PAL binary fallback");require(decodeImportedPalette(bytes("17 34 51\n"),"one.PAL").colors[0]==0xff332211,"PAL text first");
 auto native=decodeImportedPalette(bytes("{\"schemaVersion\":2,\"id\":\"fixture\",\"name\":\"Native name\",\"colors\":[\"#112233\",\"#445566\"],\"columns\":4,\"slots\":[0,null,null,1],\"names\":[\"one\",\"two\"]}"),"fallback.palette.json");require(native.name=="Native name"&&native.columns==4&&native.slots==std::vector<std::optional<std::size_t>>({0,std::nullopt,std::nullopt,1})&&native.names->at(1)=="two","native JSON sparse names precedence");
 for(auto suffix:{"json","GPL","txt","hex","csv","ACT","pal","ASE","aco"})require(supportedPaletteImportPath(std::string("fixture.")+suffix),"supported extension missing");for(auto suffix:{"png","bmp","gif","md"})require(!supportedPaletteImportPath(std::string("fixture.")+suffix),"unmigrated format exposed");
 const auto root=std::filesystem::current_path()/"build"/("palette-import-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directories(root);auto external=root/"ordered.gpl";std::ofstream(external)<<"17 34 51\n68 85 102\n";PaletteLibrary library(root);auto listed=library.list();require(listed.size()==1&&listed[0].id==externalPaletteId(external)&&listed[0].id.rfind("external-",0)==0,"folder external stable ID");const auto externalId=listed[0].id;auto saved=library.save(listed[0],externalId);require(saved.path.extension()==".json"&&std::filesystem::exists(external)&&library.list().size()==1&&library.list()[0].path==saved.path,"current saves native copy and suppresses duplicate");library.remove(externalId);require(std::filesystem::exists(external)&&library.list().size()==1&&library.list()[0].path==external,"delete native copy preserves external source");
 auto importedFile=library.importFile(external);require(importedFile.colors==gpl.colors&&importedFile.columns==2&&importedFile.id!=externalId,"picker import persists new native copy");std::ofstream(root/"bad.csv")<<"no colors\n";auto count=library.list().size();bool rejected=false;try{library.importFile(root/"bad.csv");}catch(const std::exception&){rejected=true;}require(rejected&&library.list().size()==count,"failed import created library record");
 auto snapshot=readPaletteImportBytes(external);std::ofstream(external)<<"changed";require(decodeImportedPalette(snapshot,external).colors==gpl.colors,"snapshot parser reopened file");
 rejected=false;try{decodeImportedPalette(std::vector<std::uint8_t>(64*1024*1024+1),"big.txt");}catch(const std::exception&){rejected=true;}require(rejected,"64 MiB limit");
 std::cout<<"palette-import: passed\n";return 0;
 }catch(const std::exception& error){std::cerr<<error.what()<<'\n';return 1;}}
